import { mkdir, rename, rm, stat, writeFile } from 'fs/promises';
import path from 'path';

const CUSTOM_TOOL_NAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const MAX_TOOL_NAME_LENGTH = 64;

export interface CreateToolScaffoldInput {
  name: string;
  description: string;
  parametersSchema?: Record<string, unknown>;
  handlerSource?: string;
  overwrite?: boolean;
}

export interface CreatedToolScaffold {
  folderPath: string;
  toolId: string;
}

function defaultHandlerSource(name: string): string {
  return `/**
 * ${name} — generated by custom_tool(op:create).
 * This safe default is intentionally a no-op; replace it with real behavior.
 */
export default async function handler(
  _input: Record<string, unknown>,
  _context: { agentId?: string; threadId?: string; triggerMessageId?: string }
) {
  return { ok: true, tool: ${JSON.stringify(name)} };
}
`;
}

async function pathExists(target: string): Promise<boolean> {
  try {
    await stat(target);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return false;
    throw error;
  }
}

function validateCustomToolName(rawName: string): string {
  const name = rawName.trim();
  if (!CUSTOM_TOOL_NAME.test(name) || name.length > MAX_TOOL_NAME_LENGTH) {
    throw new Error(
      'name must be 1-64 characters using lowercase letters, numbers, and single hyphens between segments'
    );
  }
  return name;
}

function customToolId(name: string): string {
  return name.replace(/-/g, '_');
}

/**
 * Write a complete custom-tool folder using a sibling staging directory, so
 * the scanner never observes a partially-authored definition/tool pair.
 */
export async function writeCustomToolScaffold(
  toolsDir: string,
  input: CreateToolScaffoldInput
): Promise<CreatedToolScaffold> {
  const name = validateCustomToolName(input.name);
  const description = input.description.trim();
  if (!description) throw new Error('description is required');
  if (
    input.parametersSchema !== undefined &&
    (input.parametersSchema === null ||
      typeof input.parametersSchema !== 'object' ||
      Array.isArray(input.parametersSchema))
  ) {
    throw new Error('parameters_schema must be a JSON object');
  }
  if (input.handlerSource !== undefined && !input.handlerSource.trim()) {
    throw new Error('handler_source must not be empty when provided');
  }

  const folderPath = path.join(toolsDir, name);
  await mkdir(toolsDir, { recursive: true });
  if ((await pathExists(folderPath)) && !input.overwrite) {
    throw new Error(
      `Tool folder already exists: ${folderPath}. Pass overwrite: true to replace it.`
    );
  }

  const nonce = `${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  const stagingPath = path.join(toolsDir, `.${name}.create-${nonce}`);
  const backupPath = path.join(toolsDir, `.${name}.backup-${nonce}`);
  let backedUp = false;

  try {
    await mkdir(stagingPath, { recursive: false });
    const definition = {
      name,
      description,
      categoryPath: 'custom',
      providerId: null,
      tier: 'standard',
      parametersSchema: input.parametersSchema ?? { type: 'object', properties: {} },
      keywords: [],
    };
    await Promise.all([
      writeFile(
        path.join(stagingPath, 'definition.json'),
        `${JSON.stringify(definition, null, 2)}\n`
      ),
      writeFile(
        path.join(stagingPath, 'tool.ts'),
        input.handlerSource ?? defaultHandlerSource(name)
      ),
    ]);

    if (await pathExists(folderPath)) {
      await rename(folderPath, backupPath);
      backedUp = true;
    }
    await rename(stagingPath, folderPath);
    if (backedUp) await rm(backupPath, { recursive: true, force: true });
  } catch (error) {
    await rm(stagingPath, { recursive: true, force: true });
    if (backedUp && !(await pathExists(folderPath))) {
      await rename(backupPath, folderPath);
    }
    throw error;
  }

  return { folderPath, toolId: customToolId(name) };
}
